tasks.solutionCode:
const defaultCategories = ['Electronics', 'Books', 'Clothing'];

export async function seedCategories() {
  return await Promise.all(
    defaultCategories.map((name) =>
      prisma.category.upsert({
        where: { name },
        update: {},
        create: { name, slug: name.toLowerCase() },
      })
    )
  );
}

